import time, jwt

def effective_principal(db, idp, agent_id):
    a = db.get_agent(agent_id)
    if a is None or a.status != "active" or a.expires_at <= time.time():
        raise Forbidden("agent_inactive")
    owner = idp.get_user(a.owner_id)          # current record, never cached across calls
    if owner is None or owner.disabled:
        raise Forbidden("owner_deprovisioned")
    # Intersection: owner groups, narrowed to what the grant names.
    groups = {g for g in owner.groups if g.tenant == a.tenant_id}
    allowed_src, allowed_col = set(a.grant_sources), set(a.grant_collections)
    return Principal(agent_id=a.agent_id, owner_id=a.owner_id, tenant=a.tenant_id,
                     groups=groups, sources=allowed_src, collections=allowed_col)

def mint_token(key, p, aud, ttl=900):
    now = int(time.time())
    claims = {"sub": p.agent_id, "act_owner": p.owner_id, "tenant": p.tenant,
              "aud": aud, "iat": now, "exp": now + min(ttl, 900),
              "scope": " ".join(sorted(p.sources))}
    return jwt.encode(claims, key, algorithm="RS256")

def allows(p, doc):
    # Tricky part: both gates must pass. The grant narrows, the owner ACL still decides.
    return (doc.source in p.sources and (not p.collections or doc.collection in p.collections)
            and bool(p.groups & set(doc.acl_groups)))

