def run_once(db, filt, send, now):
    for s in db.subscriptions():
        for e in db.events_after(s.tenant_id, s.cursor_event_id, limit=200):
            if matches(e, s.selector) and filt.can_see(s.agent_id, e.doc_id):
                last = db.last_sent(s.sub_id, e.doc_id)
                if last and now - last.at < s.min_interval_s and e.op == "updated":
                    db.mark_coalesced(s.sub_id, e)   # newest update wins when the window closes
                else:
                    flush_pending(db, send, s, e.doc_id)
                    ok = send(s, push_body(s, e))
                    db.log_attempt(s.sub_id, e.event_id, ok)
                    if not ok:
                        break                        # do NOT advance the cursor past a failed push
            # Tricky part: advance the cursor only after the push or a deliberate skip,
            # and re-check can_see at send time, since access may change between events.
            db.advance_cursor(s.sub_id, e.event_id)

def matches(e, sel):
    if "entity_ids" in sel:
        return e.doc_id in sel["entity_ids"] or bool(set(e.entity_ids) & set(sel["entity_ids"]))
    return e.topic == sel.get("topic")

