import json, hashlib, time

READ_TOOLS = frozenset(cfg["tools"])
READ_SCOPES = frozenset(cfg["scopes"])

class Refused(Exception):
    def __init__(self, tool):
        self.body = {"code": "no_write_tool", "message": f"{tool} is not a read tool",
                     "hint": "use action layer"}

def guard_tool(name, audit):
    if name not in READ_TOOLS:
        audit.write({"event": "write_refused", "tool": name, "ts": time.time()})
        raise Refused(name)

def register_connector(manifest):
    extra = set(manifest["scopes"]) - READ_SCOPES
    if extra:
        raise ValueError(f"connector {manifest['name']} asks for non-read scopes {sorted(extra)}")

def import_bridge_tools(tools):
    # Tricky part: trust the declared effect class only as a hint; still require the name in the allow-list.
    return [t for t in tools if t.get("effect") == "read" and t["name"] in READ_TOOLS]

def inventory_snapshot(tools, scopes, sign):
    body = json.dumps({"tools": sorted(tools), "scopes": sorted(scopes)}, sort_keys=True)
    return {"body": body, "sha256": hashlib.sha256(body.encode()).hexdigest(), "sig": sign(body)}
